parameters.jsCode:
const webhook = $('Entrada WhatsApp/Webhook').first().json;
const body = webhook.body || webhook;
const originalMessage = body.message || body.text || webhook.message || webhook.text || '';
const sessionId = String(body.session_id || body.phone || body.from || body.sender || 'local-test');
const raw = $json.choices?.[0]?.message?.content || '{}';
let entities = {};
try {
  const cleaned = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  entities = JSON.parse(cleaned);
} catch (error) {
  entities = {};
}
const text = String(originalMessage).replace(/\s+/g, ' ').trim();
const lower = text.toLowerCase();
const nameMatch = text.match(/\b(?:soy|me llamo|mi nombre es)\s+([A-Z][a-z]+)\b/i);
const yearMatch = text.match(/\b(19\d{2}|20\d{2})\b/);
const addressMatch = text.match(/(?:direccion|dirección)\s*(?:es|:)?\s*(.+)$/i);
const cityStateMatch = text.match(/(?:estoy en|vivo en|me encuentro en)\s+([^,.]+),\s*([^,.]+)/i);
const vehicleForMatch = text.match(/\bpara\s+(?:un|una|mi)?\s*([A-Za-z0-9-]+(?:\s+[A-Za-z0-9-]+)?)\b/i);
if (!entities.nombre && nameMatch) entities.nombre = nameMatch[1];
if (!entities.anio_vehiculo && yearMatch) entities.anio_vehiculo = yearMatch[1];
if (addressMatch) {
  const deterministicAddress = addressMatch[1].trim();
  if (!entities.direccion_envio || deterministicAddress.length > String(entities.direccion_envio).length) {
    entities.direccion_envio = deterministicAddress;
  }
}
if ((!entities.ciudad || !entities.estado) && cityStateMatch) { entities.ciudad = cityStateMatch[1].trim(); entities.estado = cityStateMatch[2].trim(); }
if (/\bversa\b/i.test(text)) entities.vehiculo = 'Nissan Versa';
else if (/\bsentra\b/i.test(text)) entities.vehiculo = /b13/i.test(text) ? 'Nissan Sentra B13' : 'Nissan Sentra';
else if (/\baveo\b/i.test(text)) entities.vehiculo = 'Chevrolet Aveo';
else if (/\bmarch\b/i.test(text)) entities.vehiculo = 'Nissan March';
else if (vehicleForMatch) entities.vehiculo = vehicleForMatch[1].trim();
if (/\bl-47-650\b/i.test(text)) entities.producto_interes = 'LTH L-47-650';
if (/filtro de aceite/i.test(text)) { entities.categoria = 'filtro de aceite'; entities.producto_interes = 'filtro de aceite'; }
else if (/balatas?/i.test(text)) entities.categoria = 'balatas';
else if (/bater/i.test(text)) entities.categoria = 'bateria';
else if (/amortiguador/i.test(text)) entities.categoria = 'amortiguador';
else if (/banda de distrib/i.test(text)) entities.categoria = 'banda de distribucion';
else if (/bomba de agua/i.test(text)) entities.categoria = 'bomba de agua';
if (/\b(si|sí),?\s*(quiero comprar|continuar)|\b(quiero comprar|lo compro|hacer pedido|mandamelo|mándamelo)\b/i.test(lower) || entities.direccion_envio) entities.desea_comprar = true;
const staticData = $getWorkflowStaticData('global');
const previous = staticData[sessionId] || {};
const merged = { ...previous };
for (const [key, value] of Object.entries(entities)) {
  if (value !== null && value !== undefined && value !== '') merged[key] = value;
}
if (entities.desea_comprar !== true && merged.desea_comprar !== true) merged.desea_comprar = false;
staticData[sessionId] = merged;
const search = merged.vehiculo || merged.producto_interes || merged.categoria || text;
return [{ json: { sessionId, entities: merged, originalMessage: text, search } }];

const incoming = $input.all().map(item => item.json);
const products = Array.isArray($json) ? $json : (incoming[0]?.id ? incoming : []);
const parsed = $('Parsear JSON del LLM').first().json;
const entities = parsed.entities;
const vehicle = (entities.vehiculo || '').toLowerCase();
let candidates = products;
if (vehicle) {
  candidates = products.filter(product => product.compatibilidad_general.some(item => {
    const compatible = item.toLowerCase();
    const shortVehicle = vehicle.replace('nissan ', '').replace('chevrolet ', '').replace('volkswagen ', '');
    return vehicle.includes(compatible) || compatible.includes(shortVehicle);
  }));
}
const selected = candidates[0] || null;
const missing = [];
if (!entities.vehiculo) missing.push('modelo del vehiculo');
if (!entities.anio_vehiculo) missing.push('anio del vehiculo');
if (!entities.ciudad || !entities.estado) missing.push('ciudad y estado');
let response;
const explicitBuy = /quiero comprar|lo compro|hacer pedido|mandamelo|mándamelo|direccion|dirección/i.test(parsed.originalMessage || '');
const wantsToBuy = entities.desea_comprar === true && explicitBuy;
const hasShippingAddress = Boolean(entities.direccion_envio && /\d/.test(entities.direccion_envio));
if (wantsToBuy && hasShippingAddress) {
  response = 'Gracias. Registre tu solicitud de compra y la direccion de envio. Un asesor puede validar compatibilidad final antes de surtir el pedido.';
} else if (!selected) {
  const category = entities.categoria || entities.producto_interes || 'ese producto';
  const vehicleText = entities.vehiculo ? ` para ${entities.vehiculo}` : '';
  response = `Por ahora no encontre ${category}${vehicleText} en el catalogo disponible. Puedo registrar tu solicitud para que un asesor la revise. Me compartes tu nombre, ciudad y estado?`;
} else if (missing.length) {
  if ((entities.categoria || '').toLowerCase().includes('balata') && !entities.vehiculo) {
    response = 'Claro. Para ayudarte mejor, me puedes compartir el modelo, anio de tu vehiculo y la ciudad donde te encuentras?';
  } else {
    response = `Claro. Tenemos ${selected.categoria} ${selected.marca} ${selected.modelo} que puede ser compatible de forma general con ${selected.compatibilidad_general.join(', ')}. Para validar mejor, me puedes compartir ${missing.join(', ')}?`;
  }
} else if (wantsToBuy && !hasShippingAddress) {
  response = `Gracias${entities.nombre ? ', ' + entities.nombre : ''}. Para continuar con la compra de ${selected.categoria} ${selected.marca} ${selected.modelo}, me compartes la direccion de envio?`;
} else {
  response = `Gracias${entities.nombre ? ', ' + entities.nombre : ''}. ${selected.categoria} ${selected.marca} ${selected.modelo} esta disponible en ${selected.ciudad}, ${selected.estado}, con ${selected.stock} unidades en stock y tiene un precio de $${Number(selected.precio).toLocaleString('es-MX')} ${selected.moneda}. Deseas continuar con la compra o prefieres que un asesor revise primero compatibilidad?`;
}
const staticData = $getWorkflowStaticData('global');
staticData[parsed.sessionId] = { ...entities, producto_interes: selected ? `${selected.categoria} ${selected.marca} ${selected.modelo}` : entities.producto_interes };
return [{ json: { response, sessionId: parsed.sessionId, entities: staticData[parsed.sessionId], selectedProduct: selected } }];

const business = $('Reglas Deterministas').first().json;
const lead = $json.id ? $json : null;
return [{ json: { reply: business.response, lead } }];
